fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // Invariant: 
    // The search interval [low, high] is within bounds of v.
    // The target k is guaranteed to exist in v[low..=high].
    // The size of the interval strictly decreases each iteration.
    let mut low: usize = 0;
    let mut high: usize = v.len() - 1;

    while low < high {
        // Choose middle index to avoid overflow:
        // mid is always between low and high.
        let mid = low + (high - low) / 2;

        if v[mid] < k {
            // If mid element < target, search right half excluding mid:
            // low will move up, interval size decreases.
            low = mid + 1;
        } else {
            // If v[mid] >= k, the target must be at mid or to the left,
            // so move high down to mid, shrinking the interval.
            high = mid;
        }
    }

    // When loop ends, low == high and v[low] == k (guaranteed by preconditions).
    low
}